static inline void sera_strassen_pack_256(float *restrict destination,
                                         const float *first,
                                         const float *second,
                                         int sign) {
    for (int i = 0; i < 256; ++i) {
        float *out = destination + (size_t)i * 256;
        const float *row_first = first + (size_t)i * 512;
        if (second == NULL) {
            for (int j = 0; j < 256; ++j)
                out[j] = row_first[j];
        } else {
            const float *row_second = second + (size_t)i * 512;
            if (sign > 0) {
                for (int j = 0; j < 256; ++j)
                    out[j] = row_first[j] + row_second[j];
            } else {
                for (int j = 0; j < 256; ++j)
                    out[j] = row_first[j] - row_second[j];
            }
        }
    }
}

