/* Copy or combine stride512 quadrants into a dense stride256 operand. */
static inline void sera_strassen_pack_256(float *restrict destination,
                                         const float *first,
                                         const float *second,
                                         int sign) {
    for (int i = 0; i < 256; ++i) {
        float *out = destination + (size_t)i * 256;
        const float *row_first = first + (size_t)i * 512;
        if (second == NULL) {
            for (int j = 0; j < 256; j += 4) {
                const float32x4_t first_values = vld1q_f32(row_first + j);
                vst1q_f32(out + j, first_values);
            }
        } else {
            const float *row_second = second + (size_t)i * 512;
            if (sign > 0) {
                for (int j = 0; j < 256; j += 4) {
                    const float32x4_t first_values = vld1q_f32(row_first + j);
                    const float32x4_t second_values = vld1q_f32(row_second + j);
                    vst1q_f32(out + j, vaddq_f32(first_values, second_values));
                }
            } else {
                for (int j = 0; j < 256; j += 4) {
                    const float32x4_t first_values = vld1q_f32(row_first + j);
                    const float32x4_t second_values = vld1q_f32(row_second + j);
                    vst1q_f32(out + j, vsubq_f32(first_values, second_values));
                }
            }
        }
    }
}
